-- Registry PUBLISHPLUGIN-NOT-OFFERED-FROM-CLOUD-SESSION: skill updates go to Sean as one .zip upload (Sean, 2026-10-28).
-- Applied through ve-once-registry-skill-upload (canon ops-supabase-write-once-function). Guarded.
update public.error_registry set fix_steps = '["Default (Sean, 2026-10-28): package the skill folder (SKILL.md + references/) as one .zip and hand it to Sean with SendUserFile. Sean uploads it in claude.ai Skills settings. No terminal, no new chat. If the old version came from a plugin, Sean turns that copy off after the upload so only one bcps-brand-kit is active.", "Keep the source in lesaruss/lesaruss-context under skills/<name>/ and merge it there first, so the zip and the repo match.", "Do not send Sean to a terminal or a second chat for a skill update unless he asks.", "No HQ or API path writes into claude.ai skills; do not promise one."]'::jsonb, updated_at = now()
where error_code = 'PUBLISHPLUGIN-NOT-OFFERED-FROM-CLOUD-SESSION' and fix_steps::text not like '%Default (Sean, 2026-10-28)%';
